export PYTHONDONTWRITEBYTECODE=1
cleanup() { /usr/bin/umount -R "$PWD/mnt" 2>/dev/null; /usr/sbin/dmsetup remove_all 2>/dev/null; /usr/sbin/losetup -D 2>/dev/null; /usr/bin/rm -f ./*.img ./*.txt; }
trap cleanup EXIT
mapk=(); mapv=()
reg() { mapk+=("$1"); mapv+=("$2"); }
norm() { local s i; s=$(< "$1"); for i in "${!mapk[@]}"; do s=${s//"${mapk[i]}"/${mapv[i]}}; done; while [[ $s == *'  '* ]]; do s=${s//'  '/ }; done; printf '%s\n' "$s"; }
normv() { local s=$1 i; for i in "${!mapk[@]}"; do s=${s//"${mapk[i]}"/${mapv[i]}}; done; while [[ $s == *'  '* ]]; do s=${s//'  '/ }; done; printf '%s' "$s"; }
at() { REPLY=$(/usr/sbin/losetup -fP --show "$1") || echo "losetup failed: $1" >&2; local n=${REPLY#/dev/} want=${2:-0} i c p; for ((i=0;i<100;i++)); do c=0; for p in /sys/block/$n/${n}p*; do [[ -b /dev/${p##*/} ]] && c=$((c+1)); done; ((c>=want)) && break; read -t 0.1 -r _ <> <(:) || :; done; }
MK=/usr/sbin/mke2fs

